import strop

text = '  Hello, World\t\n'
table = strop.maketrans('abc', 'xyz')
unchanged = 'already lower'

RESULT = (
    strop.whitespace,
    strop.lowercase,
    strop.uppercase,
    len(table),
    table[97:100],
    table[:3],
    strop.maketrans('', '') == table[:97] + 'abc' + table[100:],
    strop.translate('aabbcc', table),
    strop.translate('aabbcc', table, 'b'),
    strop.translate(unchanged, table, 'q') is unchanged,
    strop.lower(text),
    strop.upper(text),
    strop.swapcase(text),
    strop.capitalize('hELLO world'),
    strop.lower(unchanged) is unchanged,
    strop.lower(u'ABC'),
    strop.lower(u'abc'),
    strop.strip(text),
    strop.lstrip(text),
    strop.rstrip(text),
    strop.strip('   '),
    strop.split(' a  b\tc\n '),
    strop.split(' a  b\tc d ', None, 2),
    strop.split('a,b,,c', ','),
    strop.splitfields('a::b::c', '::', 1),
    strop.join(['a', 'b', 'c']),
    strop.joinfields(('a', 'b'), '-'),
    strop.join('xyz', '+'),
    strop.join(['only']),
    strop.join([]),
    strop.find('hello world', 'o'),
    strop.find('hello world', 'o', 5),
    strop.find('hello world', 'o', -3),
    strop.find('hello', '', 2),
    strop.find('hello', '', 9),
    strop.rfind('hello world', 'o'),
    strop.rfind('hello world', 'o', 0, 6),
    strop.rfind('hello', '', 1, 3),
    strop.count('aaaa', 'aa'),
    strop.count('banana', 'a', 2),
    strop.count('abc', ''),
    strop.count('abc', '', 5),
    strop.replace('banana', 'a', 'o'),
    strop.replace('banana', 'a', 'o', 2),
    strop.replace('banana', 'a', 'o', 0),
    strop.replace(unchanged, 'z', 'y') is unchanged,
    strop.replace('aaa', 'a', ''),
    strop.expandtabs('a\tbc\td\n\te'),
    strop.expandtabs('a\tb', 4),
)
